CommandLine:
"C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe" -Command "try { [Console]::OutputEncoding=[System.Text.Encoding]::UTF8 } catch {}
$ErrorActionPreference = 'Continue'
$runDir = 'C:\Projects\llm_mvp_core\docs\plans\evidence\extension-full-readiness-dual-path\scenario-execution\frdp-p01-cursor-token-savings-baseline\same-scenario-ui-proof-row12\run-20260625T080900Z\webview-control-diagnostic-run-20260625T111205Z'
$procs = Get-CimInstance Win32_Process | Where-Object { $_.Name -match 'Cursor|Code|electron|node' -or $_.CommandLine -match 'cursor-xiigen|extensionDevelopment|remote-debugging|inspect|extensionHost' } | Select-Object ProcessId, ParentProcessId, Name, ExecutablePath, CommandLine
$procs | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $runDir 'cursor-related-processes-commandlines.json') -Encoding UTF8

$ports = @()
try {
  $tcp = Get-NetTCPConnection -State Listen -ErrorAction Stop
  foreach ($p in $procs) {
    $matches = $tcp | Where-Object { $_.OwningProcess -eq $p.ProcessId }
    foreach ($m in $matches) {
      $ports += [pscustomobject]@{pid=$p.ProcessId; name=$p.Name; localAddress=$m.LocalAddress; localPort=$m.LocalPort; state=$m.State; commandLine=$p.CommandLine}
    }
  }
} catch {
  $ports += [pscustomobject]@{error=$_.Exception.Message}
}
$ports | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $runDir 'cursor-related-listening-ports.json') -Encoding UTF8

# Try common local Chrome DevTools endpoints found from ports plus common defaults.
$debugResults = @()
$portsToTry = New-Object System.Collections.Generic.HashSet[int]
foreach ($pt in @($ports | Where-Object { $_.localPort } | Select-Object -ExpandProperty localPort)) { [void]$portsToTry.Add([int]$pt) }
foreach ($pt in 9222,9229,9230,5173,3000) { [void]$portsToTry.Add($pt) }
foreach ($pt in $portsToTry) {
  foreach ($host in '127.0.0.1','localhost') {
    $url = \"http://$host`:$pt/json/list\"
    try {
      $resp = Invoke-WebRequest -UseBasicParsing -Uri $url -TimeoutSec 2
      $debugResults += [pscustomobject]@{host=$host; port=$pt; url=$url; status=$resp.StatusCode; body=$resp.Content}
    } catch {
      $debugResults += [pscustomobject]@{host=$host; port=$pt; url=$url; error=$_.Exception.Message}
    }
  }
}
$debugResults | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $runDir 'devtools-json-list-probe.json') -Encoding UTF8
[pscustomobject]@{processCount=@($procs).Count; listeningPorts=@($ports | Where-Object {$_.localPort} | Select-Object pid,name,localAddress,localPort); devtoolsReachable=@($debugResults | Where-Object {$_.status -eq 200} | Select-Object host,port,url,status,body)} | ConvertTo-Json -Depth 8"
